* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  background: #0a0a0f;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: 'Segoe UI', sans-serif;
  overflow: hidden;
}
#gameWrapper {
  position: relative;
  width: 960px;
}
#hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: linear-gradient(180deg, #1a1a2e 0%, #0f0f1a 100%);
  border-radius: 8px 8px 0 0;
  border: 1px solid #333;
  border-bottom: none;
}
.player-hud { flex: 1; }
.player-hud.left { padding-right: 20px; }
.player-hud.right { padding-left: 20px; text-align: right; }
.player-name {
  font-size: 14px;
  font-weight: bold;
  margin-bottom: 4px;
  text-shadow: 0 0 8px rgba(255,255,255,0.3);
}
.health-bar-bg, .energy-bar-bg {
  height: 18px;
  background: #222;
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 3px;
  border: 1px solid #444;
}
.energy-bar-bg { height: 8px; }
.health-bar {
  height: 100%;
  transition: width 0.3s ease;
  border-radius: 2px;
}
.health-bar.p1 {
  background: linear-gradient(90deg, #ff4444, #ff8800);
  float: right;
}
.health-bar.p2 {
  background: linear-gradient(90deg, #4488ff, #00ccff);
}
.energy-bar {
  height: 100%;
  transition: width 0.2s ease;
  border-radius: 2px;
}
.energy-bar.p1 {
  background: linear-gradient(90deg, #ffaa00, #ffff00);
  float: right;
}
.energy-bar.p2 {
  background: linear-gradient(90deg, #00aaff, #00ffcc);
}
#roundInfo {
  text-align: center;
  min-width: 100px;
}
#timer {
  font-size: 32px;
  font-weight: 900;
  color: #ffcc00;
  text-shadow: 0 0 10px rgba(255,200,0,0.5);
  line-height: 1;
}
#round {
  font-size: 11px;
  color: #888;
  letter-spacing: 2px;
}
#score {
  font-size: 18px;
  color: #fff;
  font-weight: bold;
}
#gameCanvas {
  display: block;
  background: #111;
  border: 1px solid #333;
  border-top: none;
  image-rendering: pixelated;
}
#controls {
  display: flex;
  justify-content: space-around;
  padding: 8px;
  background: #0f0f1a;
  border-radius: 0 0 8px 8px;
  border: 1px solid #333;
  border-top: none;
}
.control-group {
  display: flex;
  gap: 8px;
  font-size: 11px;
  color: #666;
  align-items: center;
}
.control-group .label {
  color: #aaa;
  font-weight: bold;
  margin-right: 4px;
}
#overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: rgba(0,0,0,0.75);
  z-index: 10;
  pointer-events: none;
}
#overlay.hidden { display: none; }
#overlayText {
  font-size: 48px;
  font-weight: 900;
  color: #ffcc00;
  text-shadow: 0 0 20px rgba(255,200,0,0.6), 0 4px 8px rgba(0,0,0,0.8);
  letter-spacing: 4px;
}
#overlaySub {
  font-size: 16px;
  color: #aaa;
  margin-top: 12px;
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Game constants
const GRAVITY = 0.6;
const GROUND_Y = 350;
const JUMP_FORCE = -15;
const MOVE_SPEED = 5;
const ATTACK_DAMAGE = 10;
const ATTACK_RANGE = 60;
const ATTACK_DURATION = 15;

// Player class
class Player {
    constructor(x, color, controls) {
        this.x = x;
        this.y = GROUND_Y;
        this.width = 50;
        this.height = 80;
        this.color = color;
        this.velocityX = 0;
        this.velocityY = 0;
        this.health = 100;
        this.isJumping = false;
        this.isAttacking = false;
        this.attackFrame = 0;
        this.facingRight = x < canvas.width / 2;
        this.controls = controls;
        this.isDead = false;
    }

    update(keys) {
        if (this.isDead) return;

        // Movement
        if (keys[this.controls.left]) {
            this.velocityX = -MOVE_SPEED;
            this.facingRight = false;
        } else if (keys[this.controls.right]) {
            this.velocityX = MOVE_SPEED;
            this.facingRight = true;
        } else {
            this.velocityX = 0;
        }

        // Jump
        if (keys[this.controls.jump] && !this.isJumping) {
            this.velocityY = JUMP_FORCE;
            this.isJumping = true;
        }

        // Attack
        if (keys[this.controls.attack] && !this.isAttacking) {
            this.isAttacking = true;
            this.attackFrame = ATTACK_DURATION;
        }

        // Apply gravity
        this.velocityY += GRAVITY;

        // Update position
        this.x += this.velocityX;
        this.y += this.velocityY;

        // Ground collision
        if (this.y >= GROUND_Y) {
            this.y = GROUND_Y;
            this.velocityY = 0;
            this.isJumping = false;
        }

        // Wall collision
        if (this.x < 0) this.x = 0;
        if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;

        // Attack animation
        if (this.isAttacking) {
            this.attackFrame--;
            if (this.attackFrame <= 0) {
                this.isAttacking = false;
            }
        }
    }

    draw() {
        if (this.isDead) return;

        // Draw body
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y - this.height, this.width, this.height);

        // Draw head
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x + 10, this.y - this.height - 20, 30, 20);

        // Draw eyes
        ctx.fillStyle = 'white';
        if (this.facingRight) {
            ctx.fillRect(this.x + 25, this.y - this.height - 15, 8, 8);
            ctx.fillRect(this.x + 32, this.y - this.height - 15, 8, 8);
        } else {
            ctx.fillRect(this.x + 10, this.y - this.height - 15, 8, 8);
            ctx.fillRect(this.x + 17, this.y - this.height - 15, 8, 8);
        }

        // Draw attack effect
        if (this.isAttacking) {
            ctx.fillStyle = 'rgba(255, 255, 0, 0.7)';
            const attackX = this.facingRight ? 
                this.x + this.width : 
                this.x - ATTACK_RANGE;
            ctx.fillRect(attackX, this.y - this.height, ATTACK_RANGE, this.height);
        }
    }

    getAttackBox() {
        if (!this.isAttacking) return null;

        return {
            x: this.facingRight ? 
                this.x + this.width : 
                this.x - ATTACK_RANGE,
            y: this.y - this.height,
            width: ATTACK_RANGE,
            height: this.height
        };
    }

    takeDamage(damage) {
        this.health -= damage;
        if (this.health <= 0) {
            this.health = 0;
            this.isDead = true;
        }
    }
}

// Initialize players
let player1, player2;
let gameRunning = true;

function initGame() {
    player1 = new Player(100, '#ff4444', {
        left: 'KeyA',
        right: 'KeyD',
        jump: 'KeyW',
        attack: 'Space'
    });

    player2 = new Player(650, '#4444ff', {
        left: 'ArrowLeft',
        right: 'ArrowRight',
        jump: 'ArrowUp',
        attack: 'ArrowDown'
    });

    gameRunning = true;
    document.getElementById('gameOver').style.display = 'none';
    document.getElementById('restartBtn').style.display = 'none';
}

// Key handling
const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.code] = true;
    e.preventDefault();
});

document.addEventListener('keyup', (e) => {
    keys[e.code] = false;
});

// Collision detection
function checkCollision(rect1, rect2) {
    return rect1.x < rect2.x + rect2.width &&
           rect1.x + rect1.width > rect2.x &&
           rect1.y < rect2.y + rect2.height &&
           rect1.y + rect1.height > rect2.y;
}

// Game loop
function gameLoop() {
    if (!gameRunning) {
        requestAnimationFrame(gameLoop);
        return;
    }

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw ground
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);

    // Update players
    player1.update(keys);
    player2.update(keys);

    // Check attacks
    const attackBox1 = player1.getAttackBox();
    const attackBox2 = player2.getAttackBox();

    if (attackBox1 && checkCollision(attackBox1, player2)) {
        player2.takeDamage(ATTACK_DAMAGE);
    }

    if (attackBox2 && checkCollision(attackBox2, player1)) {
        player1.takeDamage(ATTACK_DAMAGE);
    }

    // Draw players
    player1.draw();
    player2.draw();

    // Update health bars
    document.getElementById('player1Health').style.width = player1.health + '%';
    document.getElementById('player2Health').style.width = player2.health + '%';

    // Check game over
    if (player1.isDead || player2.isDead) {
        gameRunning = false;
        const winner = player1.isDead ? 'Player 2 (Blue) Wins!' : 'Player 1 (Red) Wins!';
        document.getElementById('gameOver').textContent = winner;
        document.getElementById('gameOver').style.display = 'block';
        document.getElementById('restartBtn').style.display = 'block';
    }

    requestAnimationFrame(gameLoop);
}

// Restart game
function restartGame() {
    initGame();
}

// Start game
initGame();
gameLoop();

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const status = document.getElementById('status');

// 游戏状态
let gameRunning = false;
let gameOver = false;

// 物理常量
const GRAVITY = 0.6;
const GROUND_Y = 350;
const JUMP_FORCE = -15;

// 玩家类
class Player {
    constructor(x, color, name) {
        this.x = x;
        this.y = GROUND_Y;
        this.width = 50;
        this.height = 80;
        this.color = color;
        this.name = name;
        this.velocityX = 0;
        this.velocityY = 0;
        this.health = 100;
        this.isJumping = false;
        this.isAttacking = false;
        this.attackCooldown = 0;
        this.facingRight = x < canvas.width / 2;
    }

    update() {
        // 应用重力
        this.velocityY += GRAVITY;

        // 更新位置
        this.x += this.velocityX;
        this.y += this.velocityY;

        // 地面碰撞
        if (this.y >= GROUND_Y) {
            this.y = GROUND_Y;
            this.velocityY = 0;
            this.isJumping = false;
        }

        // 边界检测
        if (this.x < 0) this.x = 0;
        if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;

        // 攻击冷却
        if (this.attackCooldown > 0) {
            this.attackCooldown--;
            if (this.attackCooldown === 0) {
                this.isAttacking = false;
            }
        }

        // 摩擦力
        this.velocityX *= 0.85;
    }

    draw() {
        // 身体
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y - this.height, this.width, this.height);

        // 头部
        ctx.fillStyle = '#ffdbac';
        ctx.beginPath();
        ctx.arc(this.x + this.width/2, this.y - this.height - 15, 20, 0, Math.PI * 2);
        ctx.fill();

        // 眼睛
        ctx.fillStyle = '#000';
        const eyeOffset = this.facingRight ? 5 : -5;
        ctx.beginPath();
        ctx.arc(this.x + this.width/2 + eyeOffset, this.y - this.height - 18, 3, 0, Math.PI * 2);
        ctx.fill();

        // 攻击效果
        if (this.isAttacking) {
            ctx.fillStyle = 'rgba(255, 255, 0, 0.7)';
            const attackX = this.facingRight ? 
                this.x + this.width : 
                this.x - 40;
            ctx.fillRect(attackX, this.y - this.height + 20, 40, 40);
        }

        // 血条
        const healthBarWidth = 100;
        const healthBarHeight = 10;
        const healthBarX = this.x + (this.width - healthBarWidth) / 2;

        // 血条背景
        ctx.fillStyle = '#333';
        ctx.fillRect(healthBarX, this.y - this.height - 50, healthBarWidth, healthBarHeight);

        // 血条前景
        const healthPercent = this.health / 100;
        ctx.fillStyle = healthPercent > 0.5 ? '#00ff00' : 
                        healthPercent > 0.25 ? '#ffff00' : '#ff0000';
        ctx.fillRect(healthBarX, this.y - this.height - 50, healthBarWidth * healthPercent, healthBarHeight);

        // 名字
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 14px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(this.name, this.x + this.width/2, this.y - this.height - 60);
    }

    jump() {
        if (!this.isJumping) {
            this.velocityY = JUMP_FORCE;
            this.isJumping = true;
        }
    }

    attack() {
        if (this.attackCooldown === 0) {
            this.isAttacking = true;
            this.attackCooldown = 20;
            return true;
        }
        return false;
    }

    getAttackBox() {
        return {
            x: this.facingRight ? 
                this.x + this.width : 
                this.x - 40,
            y: this.y - this.height + 20,
            width: 40,
            height: 40
        };
    }

    takeDamage(damage) {
        this.health -= damage;
        if (this.health < 0) this.health = 0;
    }
}

// 创建玩家
let player1, player2;

function initGame() {
    player1 = new Player(100, '#ff4444', '玩家1');
    player2 = new Player(650, '#4444ff', '玩家2');
    player2.facingRight = false;
    gameRunning = true;
    gameOver = false;
    status.textContent = '战斗中！';
}

// 碰撞检测
function checkCollision(rect1, rect2) {
    return rect1.x < rect2.x + rect2.width &&
           rect1.x + rect1.width > rect2.x &&
           rect1.y < rect2.y + rect2.height &&
           rect1.y + rect1.height > rect2.y;
}

// 键盘状态
const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.key.toLowerCase()] = true;

    if (e.key.toLowerCase() === 'r' && !gameRunning) {
        initGame();
    }
});

document.addEventListener('keyup', (e) => {
    keys[e.key.toLowerCase()] = false;
});

// 游戏循环
function gameLoop() {
    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 绘制地面
    ctx.fillStyle = '#4a4a4a';
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);

    // 绘制装饰
    ctx.fillStyle = '#3a3a3a';
    for (let i = 0; i < canvas.width; i += 50) {
        ctx.fillRect(i, GROUND_Y, 25, canvas.height - GROUND_Y);
    }

    if (gameRunning && !gameOver) {
        // 玩家1控制 (WASD + F)
        if (keys['a']) {
            player1.velocityX = -5;
            player1.facingRight = false;
        }
        if (keys['d']) {
            player1.velocityX = 5;
            player1.facingRight = true;
        }
        if (keys['w']) player1.jump();

        // 玩家2控制 (方向键 + M)
        if (keys['arrowleft']) {
            player2.velocityX = -5;
            player2.facingRight = false;
        }
        if (keys['arrowright']) {
            player2.velocityX = 5;
            player2.facingRight = true;
        }
        if (keys['arrowup']) player2.jump();

        // 攻击检测
        if (keys['f'] && player1.attack()) {
            const attackBox = player1.getAttackBox();
            if (checkCollision(attackBox, player2)) {
                player2.takeDamage(10);
            }
        }

        if (keys['m'] && player2.attack()) {
            const attackBox = player2.getAttackBox();
            if (checkCollision(attackBox, player1)) {
                player1.takeDamage(10);
            }
        }

        // 更新玩家
        player1.update();
        player2.update();

        // 检查游戏结束
        if (player1.health <= 0 || player2.health <= 0) {
            gameOver = true;
            gameRunning = false;

            if (player1.health <= 0 && player2.health <= 0) {
                status.textContent = '平局！按 R 重来';
            } else if (player1.health <= 0) {
                status.textContent = '🔵 玩家2 获胜！按 R 重来';
            } else {
                status.textContent = '🔴 玩家1 获胜！按 R 重来';
            }

            setTimeout(() => {
                gameRunning = false;
            }, 100);
        }
    }

    // 绘制玩家
    if (player1 && player2) {
        player1.draw();
        player2.draw();
    }

    requestAnimationFrame(gameLoop);
}

// 启动游戏循环
gameLoop();

